window.ATLAS_QUOTES = {"jdeida":{"https://ar.wikipedia.org/wiki/تحرير_طرابلس_(2011)":{"pre":"وبعدَ هذه الاشتباكات تمكن الثوار أخيراً من السَّيطرة بالكامل على أربع مناطق كبرى في شرق العاصمة، هيَ قاعدة معيتيقة الجوية ومناطق تاجوراء وفشلوم وبن عاشور، لكن في المُقابل دفعوا ثمناً للاستيلاء على هذه المناطق 123 قتيلاً في تاجوراء وَحدها.","hi":"وقد استطاعَ الثوار أيضاً خلال هذه الاشتباكات إطلاق سراح 500 معتقل من «سجن الجديدة»، بالإضافة إلى أسرهم 35 فرداً تابعين لكتائب القذافي.","post":"أما الزحف من الخارج فكان قد بدأ بالفعل من الزاوية وجبهة جنوب العاصمة، بالإضافة إلى جبهتها الشرقية. === 21 أغسطس === اندلعت الاشتباكات مرَّة أخرى في العاصمة يومَ الأحد 21 أغسطس.","t":"تحرير طرابلس (2011) (Arabic Wikipedia)","d":""}},"maktab":{"https://en.wikipedia.org/wiki/Maktab_al-Nasser_prison":{"pre":"","hi":"Maktab al-Nasser prison is a prison in the Abu Salim district of Tripoli, Libya.","post":"Prior to the fall of Muammar Gaddafi's government in the 2011 Libyan civil war, it served as a prison and office of the internal security agency.","t":"Maktab al-Nasser prison (Wikipedia)","d":""}},"ainzara":{"https://ar.wikipedia.org/wiki/تحرير_طرابلس_(2011)":{"pre":"وفي وقت لاحق دخلَ الثوار مقرَّ التلفزيون الليبي الرسمي، وتلا ذلك توقف بثه بشكل تام.","hi":"كما حرَّروا آلاف السجناء المحتجزين في «سجن عين زارة» خلال اليوم ذاته.","post":"وقد شنت كتائب القذافي هجوماً على الثوَّار المُتمركزين في الساحة الخضراء (ساحة الشهداء) يوم الإثنين، بعدَ مُضي يوم كامل على دخولهم إليها واحتفالهم بـ«سقوط القذافي».","t":"تحرير طرابلس (2011) (Arabic Wikipedia)","d":""}},"blackhorse":{"https://archive.org/details/jprs-report_jprs-75801":{"pre":"His assignment is to monitor the recruited Tunisian elements in the sabotage camps.","hi":"The refrac- tory elements are either banished or interned in the \"Black Horse\" prison on the Tripoli International Airport road or in a new prison established by Libyan intelligence 7 kilometers from Tripoli.","post":"This use of intimida- tion is a natural thing in Libya.","t":"Near East/North Africa Report No. 2124","d":"1980-06-02"}},"towisha":{"https://en.wikipedia.org/wiki/Detention_centres_in_Libya":{"pre":"A ministerial department reporting to the Interior Ministry was created in 2012.","hi":"Its mission includes overseeing detention conditions and integrating independent detention centres into the state-run system. === Intensification of migratory flows in Libya from 2013 === From the first half of 2013, the number of migrants arriving in Libya—and departing towards Europe—began to rise significantly.","post":"According to the Frontex agency, 31,500 people landed on Italian shores between January and September 2013, compared to around 10,000 for all of 2012.","t":"Detention centres in Libya (Wikipedia)","d":""}},"cso":{"https://en.wikipedia.org/wiki/Bin_Ashur":{"pre":"United States bombing in 1986 devastated the neighbourhood.","hi":"Eiji Tanaka, the Ambassador of Japan to Libya, speculated that the U.S. bombs were intended to reach the Central Security Organization behind the Embassy of France to Libya, which received damage. == References ==","post":"","t":"Bin Ashur","d":"2026-10-18"}},"as-bab":{"https://www.cia.gov/readingroom/document/cia-rdp91-00901r000500230008-3":{"pre":"The Joint Chiefs were known to be reluctant to use force aS a response to terrorism, and had been resisting White House staff entreaties to move a third air- craft carrier into the Mediterranean to buttress the two already on patrol.","hi":"The Joint Chiefs had claimed that at least three carriers and their strike force would be needed if Libya re- sponded to a bombing with its 500 fighter aircraft.","post":"Adding a third car- rier to the task force, the Joint Chiefs explained, would disrupt the schedule of leaves for seamen and pilots.","t":"TARGET QADDAFI","d":"1987-02-22"},"https://www.cia.gov/readingroom/document/cia-rdp90-00965r000706870020-5":{"pre":"Reagan pointed to those specific messages as “ir- refutable” evidence that the Libyan regime ordered the terrorist bombing of a West Berlin nightclub 11 days ago that killed two people and wounded 230.","hi":"Another well-placed source, however, said one of the three messages had been traced to Qaddafi’s command and control center at the Bab Azizzia barracks.","post":"Declassified and Approved For Release 2011/12/19 : CIA-RDP90-00965R000706870020-5 One source yesterday said that_new_in- telligence reports show that Libya is con- tinuing, if not actually stepping up, planning for terrorist attacks against U.S. targets in . not interpret this as an ominous new deve…","t":"U.S. TARGETED QADDAFI COMPOUND AFTER TRACING TERROR MESSAGE","d":"1986-04-16"}},"as-benashour":{"https://www.cia.gov/readingroom/document/cia-rdp90-00965r000403730006-2":{"pre":"…re the command-and-control center and admin- istrative buildings of El-Azziziya Barracks in Tripoli, none of which were struck by bombs, as well as the military side of the Tripoli airport and a com- mando training site in the nearby port city of Sidi Bilal, which were hit by the other nine F-111's.","hi":"Also mistakenly hit by one F-111 assigned to attack the barracks was a heavily popu- lated residential area of Tripoli near the French Embassy.","post":"The shielded orders explain a series of strong denials after the bombing, especially by State Department officials, when it became clear that Qaddafi’s personal quarters had been a primary target.","t":"TARGET QADDAFI","d":"1987-02-22"}},"as-nato-bab":{"https://en.wikipedia.org/wiki/2011_military_intervention_in_Libya":{"pre":"21 March 2011: Obama sent a letter to the Speaker of the House of Representatives and the President Pro Tempore of the Senate claiming the actions were justified under the War Powers Resolution.","hi":"24 March 2011: In telephone negotiations, French foreign minister Alain Juppé agreed to let NATO take over all military operations on 29 March at the latest, allowing Turkey to veto strikes on Gaddafi's ground forces from that point forward.","post":"Later reports stated that NATO would take over enforcement of the no-fly zone and the arms embargo, but discussions were still underway about whether NATO would take over the protection of civilians mission.","t":"2011 military intervention in Libya (Wikipedia)","d":""}},"bt-1979-embassy":{"https://en.wikipedia.org/wiki/1979_U.S._Embassy_Burning_in_Libya":{"pre":"On 2 December 1979, the U.S.","hi":"Embassy in Tripoli, Libya, was burned during protests over allegations that the United States was involved in the Grand Mosque seizure in Mecca, Saudi Arabia.","post":"The United States had already withdrawn the U.S.","t":"1979 U.S. Embassy Burning in Libya (Wikipedia)","d":""},"https://www.cia.gov/readingroom/document/cia-rdp90-00965r000302640078-5":{"pre":"…ged Ameri- cans to leave Libya, but there was no ef- tort to make it compulsory. | ing the crisis over the American hostages in Iran, the United States. banned the import of Iranian oil, froze’ Iran’s assets in this country, broke dip. lomatic relations and forbade most | Americans totravel to Iran.","hi":"Ofticially, the United States still has diplomatic relations with Libya, but all | American diplomats left Tripoli, the capital, in 1980 after a mob burned dora. the American Embassy.","post":"STAT Embargo on Oil Imports Weighed State Department officials said that on Americans’ living in or traveling to that country. ig Presently, some 1,500 ‘Americans, al. most all of thern in the oil industry, are employed in Libya.","t":"REAGAN WEIGHS ECONOMIC STEPS AGAINST LIBYANS","d":"1981-12-08"},"https://www.cia.gov/readingroom/document/cia-rdp90-00552r000100990092-3":{"pre":"Billy Car-: ter’s,.relations.; with . the Libyans?-.... ‘I Jease the. hostages.- “Our -relations were very ale ‘then; ** one official said,’ and Brzezin- 4 (‘ski felt that using Carter would dem- | -onstrate to the Libyans that he want: | bes to make a. serious proposition.","hi":"Meets Five days after the Brzezinski-Car- : ter-Houderi meeting; mobs in Tripoli + -burned the American Embassy there. | It was sometime after that incident * that Qaddafi asked Khomeini to re-: : “a wieaede ke ee f ie a tad «ie Approved For Release 2010/06/24 : CIA-RDP90-00552R000100990092-3 WADHLNULUIN FruolL 23 JULY 1980 The explanation that Brzezinski ini-? tiated this meeting by calling Billy: Carter was disputed’ yesterday by a: government official who was intimate- ly involved in the early diplomatic ef- forts to free the American hostages.","post":"This source, who had: heard of Brze- zinski’s dealings with Billy Carter and the Libyan charge- many months be- fore -yesterday’s. announcement, told The Washington Post that it was Billy Carter who asked Brzezinski to: meet, and not the other way around.","t":"BILLY CARTER USED BY BRZEZINSKI AS LIBYA GO-BETWEEN","d":"1980-07-23"}},"bt-1984-bab":{"https://en.wikipedia.org/wiki/1984_Libyan_coup_attempt":{"pre":"Libyan officials later confirmed that these incidents were carried out by the very same group that mounted the May 8 attack.","hi":"The authorities responded with increased security measures, including the patrolling of city streets. == Attack == At approximately 7:00 a.m. on 8 May 1984, a group of 20 to 30 gunmen assaulted the Bab al-Azizia barracks on the southern outskirts of Tripoli, a heavily fortified compound protected by electrified fences, bunkers and guard towers that served as Gaddafi's residence.","post":"The attackers were armed with rocket-propelled grenades and automatic weapons.","t":"1984 Libyan coup attempt (Wikipedia)","d":""},"https://www.cia.gov/readingroom/document/cia-rdp90-00552r000505250009-7":{"pre":"Revolutionary guards now control the distribution of live ammunition at the bases, one well- placed diplomat said.","hi":"Diplomats say the Revolutionary Committees and Guards began to grow in numbers and influence shortly after 12 men attacked the Bab el-Azziziya barracks on May 8, 1984, in an attempt officers have resented the decline in their living standards due to a fall in Libyan income from $22 billion in 1980 ‘to between $8 billion and $8 billion last Colonel Ishkal had reportedly fa- vored slashing investments in other sectors to solve the economic crisis, which he saw as potentially destabiliz- ing within the military, diplomats gaid.","post":"But Colonel Qaddafi and Major Jal- loud, who now supervises both . the Revolutionary Guards and Revolution- ary Committees, have preferred to'use the economic crisis to speed up’ the revolution and to justify.drastic actions — such as increasing the role of the revolutionary vanguards ~- that might …","t":"LIBYAN MILITARY TERMED RESTIVE UNDER QADDAFI","d":"1986-01-14"},"https://www.cia.gov/readingroom/document/cia-rdp90-00965r000100120080-3":{"pre":"The world learned some confused details of the ~ attempt, which began to unravel on May 6, when. the leader of NFSL’s military wing, Ahmed Ibrahim, Ahwas, was caught and killed trying to infiltrate P Libya from Tunisia.","hi":"Two days later, a five-hour gun . battle at the Bab Aziziya barracks, where Qaddafi often stays, ended in the death or capture of the NFSL rebels.","post":"Declassified and Approved For Release 2012/01/10 : CIA-RDP90-00965R000100120080-3","t":"CIA BACKED QADDAFI ASSASSINATION TRY","d":"1985-06-12"},"https://www.cia.gov/readingroom/document/cia-rdp90-00965r000100120021-8":{"pre":"But the agency really doesn’t have much choice; the right man turned it down.","hi":"Despite an executive order that seems to forbid it, the CIA trained and supported the National Front for the Salvation of Libya before, during and after its attempt to assassinate Qaddafi on May 8, 1984, The anti-Qaddafi group was slaughtered in a day-long battle less than a mile from the barracks where the dictator was holed up behind Soviet-made tanks and antiaircraft guns.","post":"The coup attempt was doomed before it started.","t":"QADDAFI RIVAL SPURNS CIA OVERTURES","d":"1985-11-08"}},"bt-2011-uprising":{"https://en.wikipedia.org/wiki/Battle_of_Tripoli_(2011)":{"pre":"Tripoli residents barricaded their streets and districts with burning tires, joining up with other anti-government opponents.","hi":"The uprisings quickly spread through Tripoli, notably the neighbourhoods of Fashloum, Souq al Jum'aa, Tajura and Ben Ashur, and continued throughout the rest of the city.","post":"That night, heavy fighting was reported in the neighbourhoods of Suq al Jum'a, Arrada street and 20th of Ramdan street (formerly known as 11 June Street), while anti-Gaddafi locals closed off the major Alsika street.","t":"Battle of Tripoli (2011) (Wikipedia)","d":""}},"bt-2011-tajoura":{"https://en.wikipedia.org/wiki/Battle_of_Tripoli_(2011)":{"pre":"Al Arabiya and Al Jazeera both reported that the uprising continued as of the early morning; many rebels were reported dead in the district of Qadah, while the Mitiga International Airport was reportedly surrounded by rebel forces, who attempted to obtain its surrender.","hi":"The entire Tajura district was captured by rebel forces, while fighting in Suk al-Juma, Araba district and Mitiga International Airport continued.","post":"A rebel representative stated that the operation was \"going easily\", with the end target being Gaddafi's Bab al-Azizia compound.","t":"Battle of Tripoli (2011) (Wikipedia)","d":""}},"bt-2011-mitiga":{"https://en.wikipedia.org/wiki/Battle_of_Tripoli_(2011)":{"pre":"Boats from Misrata and Zliten carrying rebel forces and arms landed in Tripoli in the early morning, joining rebels within the city in the fight.","hi":"Following the rebel amphibious landing, they advanced towards the Mitiga airbase.","post":"Al Arabiya and Al Jazeera both reported that the uprising continued as of the early morning; many rebels were reported dead in the district of Qadah, while the Mitiga International Airport was reportedly surrounded by rebel forces, who attempted to obtain its surrender.","t":"Battle of Tripoli (2011) (Wikipedia)","d":""}},"bt-2011-green":{"https://en.wikipedia.org/wiki/Battle_of_Tripoli_(2011)":{"pre":"However, it was reported later that Muhammad escaped from house arrest the next day with the aid of loyalist forces.","hi":"When the Libyana telephone company building was taken by the Tripoli Brigade, they sent out the following text message to the people of Tripoli : God is Great, We congratulate the people of Libya on the fall of the Gaddafi regime. === 22 August === By 1 am Tripoli time, rebels stated that 90% of Tripoli had been captured, including Green Square in central Tripoli.","post":"Al Jazeera and the BBC News, among other news stations, all reported and confirmed that opposition fighters had entered Green Square.","t":"Battle of Tripoli (2011) (Wikipedia)","d":""}},"bt-2011-bab":{"https://en.wikipedia.org/wiki/Battle_of_Tripoli_(2011)":{"pre":"Rebels also vandalised other statues of Gaddafi.","hi":"Following the assault on Gaddafi's compound France 24 TV reported that the Tripoli Brigade had sixty men killed in Tripoli during the previous 48 hours. === 24 August === Around noon, there were reports of fighting within the inner sanctum of the Bab al-Azizia compound, as snipers reportedly hiding in trees in the recreational area of the compound were still present.","post":"The rebels, meeting fierce resistance, continued to use heavy weaponry to expose loyalists and destroy fortifications in the centre of the compound.","t":"Battle of Tripoli (2011) (Wikipedia)","d":""}},"bt-2011-abusalim":{"https://en.wikipedia.org/wiki/Battle_of_Tripoli_(2011)":{"pre":"Reporters from inside the hotel reported that Gaddafi loyalists prevented them from leaving the compound, effectively taking them hostage amid gunfire from snipers and dwindling food supplies.","hi":"Fighting was also continuing in the Abu Salim district, which the rebels claimed to have captured the previous day, and later it was reported that loyalists were still in control of the area, as well as the al-Hadhba district.","post":"Around 5 pm, Tripoli time, all foreign reporters and staff that had been restricted to within the Rixos Al Nasr hotel were able to leave the compound in four vans of the Red Cross.","t":"Battle of Tripoli (2011) (Wikipedia)","d":""}},"bt-2011-airport":{"https://en.wikipedia.org/wiki/Battle_of_Tripoli_(2011)":{"pre":"It was confirmed that rebel forces had been in full control of Tripoli International Airport for four days, and that Gaddafi's personal planes were still on the ground.","hi":"Despite the airport being secure, clashes were still ongoing on the road near the airport.","post":"The NTC announced full amnesty to anyone close to Gaddafi who killed or captured him.","t":"Battle of Tripoli (2011) (Wikipedia)","d":""}},"mk-sharshatt":{"https://en.wikipedia.org/wiki/Battle_and_massacre_at_Shar_al-Shatt":{"pre":"","hi":"The battle and massacre at Shar al-Shatt (Arabic: شارع الشط Shār’ ash-Shaṭ; Sciara Sciat in Italian) occurred on 23 October 1911 in the village of Shar al-Shatt on the outskirts of Tripoli, Libya during the Italo-Turkish War.","post":"503 Italians were killed in Shar al -Shatt, 290 of which in the following massacre of soldiers who had surrendered.","t":"Battle and massacre at Shar al-Shatt (Wikipedia)","d":""}},"bt-2014-airport":{"https://en.wikipedia.org/wiki/Tripoli_International_Airport":{"pre":"It was expected to be completed in 2024, however due to Libya failing to keep up with payments the Italian firms delayed construction in October 2024 before the project was transferred to a Libyan contractor.","hi":"The first asphalt layer of the runway was reportedly laid in September 2025. == Airlines and destinations == As of July 2014, all passenger flights into Tripoli use Mitiga International Airport; all scheduled cargo operations into Tripoli International Airport have also ceased. == Accidents and incidents == On 9 May 1944, a Douglas Dakota III (KG548) of the RAF crashed and burned on takeoff during its delivery flight when the undercarriage retracted.","post":"It is unknown if anyone died.","t":"Tripoli International Airport (Wikipedia)","d":""}},"bt-2018":{"https://en.wikipedia.org/wiki/Battle_of_Tripoli_(2018)":{"pre":"","hi":"The Battle of Tripoli was a series of clashes in Tripoli, Libya from 27 August to 25 September 2018 during the Second Libyan Civil War.","post":"It was fought between several militias and was ended by a ceasefire. == Prelude == Clashes between militias broke out in Tripoli from 26 to 27 August 2018, touching off renewed fighting in the city after 18 months of relative calm.","t":"Battle of Tripoli (2018) (Wikipedia)","d":""}},"bt-2025":{"https://en.wikipedia.org/wiki/2025_Tripoli_clashes":{"pre":"","hi":"On 12 May 2025, clashes broke out in Tripoli, Libya, between the 444th Infantry Brigade and the Stability Support Apparatus (SSA).","post":"The fighting began after SSA commander Abdel Ghani al-Kikli was assassinated.","t":"2025 Tripoli clashes (Wikipedia)","d":""}},"mk-yarmuk-2011":{"https://en.wikipedia.org/wiki/Yarmuk_massacre":{"pre":"In total, 124 people were killed at the site. == Background information == During the final stages of the Libyan Civil War, which erupted in February 2011, forces loyal to Muammar Gaddafi engaged in brutal crackdowns against rebel groups seeking to overthrow his regime.","hi":"The Khamis Brigade, led by Gaddafis son Khamis, was known for its involvement in violent suppression tactics. == The massacre == On August 23, 2011, detainees were held in a warehouse located in the Khalida Ferjan neighborhood in Salahaddin, south of Tripoli, adjacent to the Yarmuk Military Base.","post":"The detainees, numbering approximately 153, were almost entirely civilians.","t":"Yarmuk massacre (Wikipedia)","d":""}},"mk-qasr-2011":{"https://en.wikipedia.org/wiki/Battle_of_Tripoli_(2011)":{"pre":"CNN reported a \"fierce firefight in one corner of Muammar Gaddafi's compound\" at about 2:00 local time.","hi":"Reuters reported that rebels stormed the Abu Salim district after a NATO airstrike. === 26 August === At Khilit al-Ferjan and Qasr bin Ghashir, two loyalist camps in the Tripoli area, loyalists killed \"numerous detainees\", according to eyewitnesses.","post":"Grenades and gunfire were used on a large group of prisoners after about 160 escaped from a metal hangar.","t":"Battle of Tripoli (2011) (Wikipedia)","d":""}},"bt-1980-embassies":{"https://archive.org/details/micro_IA1176908_0539":{"pre":"Tunisia is now expacting to recall its remaining consular staff from Libya, the same sources said.","hi":"Embassy Not Damaged nc041812 Paris AFP in English 1832 gmt 4 Feb 80 NC [Excerpt] Paris, Feb 4, (AFP)--Tunisian diplomats hastily evacuated their embassy in Tripoli today in the face of a mob which has earlier sacked the French mission there, the Tunisian ambassador to France said.","post":"But Ambassador Hedi Mabrouk denied earlier reports that the Tripoli embassy had been sacked and burned, and said that diplomats there had been warned by Libyan police of the approach of the demonstrators.","t":"FBIS Daily Report: Middle East & N. Africa, Vol. V No. 025, 5 February 1980","d":"1980-02-05"},"https://www.cia.gov/readingroom/document/cia-rdp90t00114r000800810001-1":{"pre":"Two gunmen kill an anti-Qadhafi Libyan journalist.","hi":"Tunisian and French Embassies in Tripoli sacked and burned by a mob while Libyan authorities took no action. j Declassified in Part - Sanitized Copy Approved for Release 2012/02/17 : CIA-RDP90T00114R000800810001-1","post":"","t":"LIBYAN INVOLVEMENT IN TERRORISM","d":"1986-01-01"}},"bt-1985-port-bomb":{"https://www.cia.gov/readingroom/document/05632817":{"pre":"In June, several Prima Linea leaders met with Red Brigades’ members in Naples—possibly to coordinate the robbery.","hi":"Possible Assassination Attempt Against Qadhafi a car bomb exploded on 14 September near the site of an economic fair in Tripoli, destroying a warehouse.","post":"Libyan leader Mu‘ammar Qadhafi reportedly was scheduled to attend the fair.","t":"TERRORISM REVIEW","d":"1985-10-07"},"https://www.cia.gov/readingroom/document/cia-rdp91b00874r000200080011-1":{"pre":"Shortages of food, water, and electricity have become a way of life for most Libyans; what is available is often expensive.","hi":"Rising Discontent Public discontent has been more open this past year, and includes instances of violence. -- There was at least one attempt to assassinate Qadhafi early in 1985; a car bomb explosion in the Tripoli port area last September also may have been aimed at Qadhafi. -- Qadhafi also has encountered growiny pressure from Libyan opposition groups, particularly the National Front for the Salvation of Libya (NFSL). -- By far the most ominous development for Qadhafi this past year is rising discontent in the armed forces. -- Qadhafi arrested scores of officers last March after discovering the first organized coup plot in two years.","post":"More officers were arrested in September, 25XK1 25X11 Sanitized Copy Approved for Release 2011/09/12 : CIA-RDP91B00874R00020008001 1-1 Sanitized Copy Approved for Release 2011/09/12 : CIA-RDP91B00874R00020008001 1-1 DISTRIBUTION: Copy 1 - DCI Copy 2 - DDI Copy 3 - NIO/NESA Copy 4 - NIO/CT Copy 5 - C…","t":"TALKING POINTS FOR THE DCI 14 JANUARY 1986 LIBYA: QADHAFI'S DOMESTIC POSITION","d":"1986-01-14"}},"bt-1985-bab-shooting":{"https://www.cia.gov/readingroom/document/cia-rdp05-01559r000400470002-2":{"pre":"Also, the public hanging of two Tripoli students was reported to have fu- eled open dissent among thousands _ of students forced to watch.","hi":"In 1985, a segment of the Libyan military reportedly launched two assassination attempts against Qad- dafi, who responded by executing dozens of officers.","post":"Staff researcher James Schwartz contributed to this report. .","t":"OFFICERS FEARED BY QADDAFI REPORTEDLY CLOSE","d":"1986-04-04"}},"bt-2011-feb21":{"https://en.wikipedia.org/wiki/Timeline_of_the_2011_Libyan_civil_war_before_military_intervention":{"pre":"Protesters seized control of the oil town of Ra's Lanuf and workers set up committees to protect the oil installations.","hi":"Activists claimed that protesters surrounded Gaddafi's Bab al-Aziza compound and were trying to storm it, but were forced back by heavy gunfire that killed up to 80 people. === 22 February === Gaddafi made a brief appearance on Libyan state television in which he said he had been speaking to the youth in Tripoli's Green Square.","post":"He also said: I am in Tripoli.","t":"Timeline of the 2011 Libyan civil war before military intervention (Wikipedia)","d":""}},"bt-2012-abusalim":{"https://en.wikipedia.org/wiki/Factional_violence_in_Libya_(2011%E2%80%932014)":{"pre":"On 16 March, a pro-autonomy demonstration was held in Benghazi, which was attacked by unknown gunmen, leaving one person dead and five injured.","hi":"On 18 March, a clash erupted between the Zintan militia and residents of Tripoli's Abu Salim district, previously loyal to Gaddafi.","post":"One militiaman was killed before a cease-fire was brokered by the district's own militia commander.","t":"Factional violence in Libya (2011–2014)","d":"2026-10-18"}},"bt-2012-dahmani":{"https://en.wikipedia.org/wiki/Factional_violence_in_Libya_(2011%E2%80%932014)":{"pre":"The attackers have also blown up the mosque attached to it and its library, filmed the events and posted the footage online.","hi":"On 25 August, the Al-Shaab Al-Dahmani mosque and shrine in central Tripoli was bulldozed in broad daylight by a group of armed Salafists, including members of the security forces.","post":"According to witnesses, when the police came, they prevented people from approaching instead of stopping the demolition, while an anonymous government officer alleged that after a small clash they sealed the area to prevent violence from spreading.","t":"Factional violence in Libya (2011–2014)","d":"2026-10-18"}},"bt-2019-abusalim":{"https://en.wikipedia.org/wiki/Western_Libya_campaign":{"pre":"Images of al-Kikli's mutilated body circulated on social media.","hi":"During 15–17 April 2019, rocket attacks using inaccurate technology occurred against three densely populated residential areas in and near the Abu Salim area of Tripoli, and were interpreted by Amnesty International (AI) as \"unlawful attacks that could amount to war crimes\".","post":"Based on information from witnesses and satellite imaging, AI stated that those launching the rockets \"failed to take necessary precautions to protect civilian lives and civilian objects\".","t":"Western Libya campaign (Wikipedia)","d":""}},"bt-2019-yarmouk":{"https://en.wikipedia.org/wiki/Western_Libya_campaign":{"pre":"…ch is the only option he has left now anyway.\" Flights were temporarily suspended; by 9 April, a coalition of local and regional militias and GNA forces had pushed Hifter's forces from the airport, and flights resumed, with clashes continuing in multiple locations on the southern fringes of Tripoli.","hi":"On 8 April, the LGA said 19 of its soldiers died in recent days in the fighting in and around Tripoli, while a spokesman for the GNA's said that \"fighting in the south of the capital had killed at least 25 people, including fighters and civilians, and wounded 80.\" From the beginning of April 2019 to mid-May 2019, southern Tripoli's Yarmouk military camp/barracks had changed hands between the GNA and the LNA at least five times.","post":"The LNA used BM-21 Grad MRLs against GNA positions in retaliation for GNA airstrikes.","t":"Western Libya campaign (Wikipedia)","d":""}},"mk-sadr-1978":{"https://archive.org/details/micro_IA1176908_0500":{"pre":"The imam, Shaykh Muhammad Sha'ta Ya'qub and 'Abbas Badr were executed by Lieutenant Faraj Bughaliyah and four under-officers who misinterpreted an order, AL-MUHARRIR said, citing a reliable Arab source.","hi":"The newspaper, organ of the Socialist Union of Popular Forces, said Imam as-Sadr and his companions were executed on a firing range near Janzur, 30 kms (20 miles) from [fripoli.","post":"Ve.","t":"FBIS Daily Report: Middle East & N. Africa, Vol. V No. 237, 7 December 1979","d":"1979-12-07"}},"mk-suwani-1982":{"https://archive.org/details/jprs-report_jprs-82800":{"pre":"OCR text: errors are likely.","hi":"LIBYA EXECUTIONS FOLLOW UNREPORTED COUP ATTEMPT Cairo AL-JUMHURIYAH in Arabic 18 Dec 82 p l [Article by the Rome correspondent for AL-JUMHURIYAH: \"Execution of Four Officers in the Libyan Army Who Attempted a Coup\"] [Text] Libyan president Mu'ammar al-Qadhdhafi has executed four of the officers who staged an undisclosed coup attempt.","post":"The executions took place in a villa belonging to Idris al-Sanusi, former king of Libya, at the Suwani bin Yadim cattle farm located 20 miles south of the city of Tripoli, which Libyan intelligence uses for interrogation and torture purposes.","t":"Near East/North Africa Report No. 2701","d":"1983-02-03"}},"mk-gargaresh-2011":{"https://en.wikipedia.org/wiki/Khamis_Brigade":{"pre":"On 23 August 2011, the Khamis Brigade killed around 50 prisoners in a Tripoli warehouse and then set fire to the warehouse.","hi":"On 29 August 2011, Khamis Gaddafi was killed in fighting in Tarhuna, On 9 September, the NTC health minister said that the Khamis Brigade had lost around 9,000 soldiers during the war, it is unknown who may have commanded remnants of the Khamis Brigade in the closing days of the 2011 Libyan civil war. == See also == 4th Armoured Division (Syria) Republican Guard (Syria) == References == == External links == Khamis Army Shoots One In The Head\", vspahi, 2011-02-18 (YouTube) \"Wounded Soldier of Khamis (Gadhafi's Son) LIBYA\", MeddiTV, 2011-02-18 (YouTube) Joshi, Shashank (22 August 2011).","post":"\"Analysis: Why Gaddafi's crack troops melted away\".","t":"Khamis Brigade (Wikipedia)","d":""}},"mk-janzour-2012":{"https://en.wikipedia.org/wiki/Factional_violence_in_Libya_(2011%E2%80%932014)":{"pre":"Bani Walid clashes Uprising started in Bani Walid on 23 January 2012 due to an incident in the city of Bani Walid in which the \"May 28 Brigade\" militia wished to arrest local men in unclear circumstances.","hi":"The May 28 Brigade and their compound were then attacked by local fighters who then took control of the town. ==== February 2012 ==== On 6 February, seven male black Libyan civilians from Tawergha were killed by militias who raided their makeshift refugee camp at a former naval academy in Janzour, a suburb of Tripoli.","post":"The survivors said that they appeared to be from Misrata because of their license plates, though the Misrata militia denied this.","t":"Factional violence in Libya (2011–2014)","d":"2026-10-18"}},"mk-corinthia-2015":{"https://en.wikipedia.org/wiki/Corinthia_Hotel_Tripoli":{"pre":"It is run by the Maltese Corinthia Hotels International (CHI) plc hotels management company.","hi":"The hotel was opened in 2003 by Prime Minister, Shukri Ghanem [More information required]. == 2015 terror attack == On 27 January 2015 ten people, including five foreigners from France, Italy, Turkey, United Kingdom and the American Crucible LLC security contractor David Berry, were killed in a gun attack.","post":"Prior to this attack, six people were injured in a car bomb explosion near the hotel.","t":"Corinthia Hotel Tripoli (Wikipedia)","d":""}},"as-nato-khamis":{"https://en.wikipedia.org/wiki/Khamis_Brigade":{"pre":"Another report stated that officers at the air force school had mutinied and the adjacent air force base had been overwhelmed.","hi":"On 18 April, the headquarters of the Khamis Brigade near Tripoli was bombed and destroyed by NATO planes that took part in the 2011 military intervention in Libya.","post":"According to NATO sources, the headquarters had been used to coordinate and lead attacks on civilians.","t":"Khamis Brigade (Wikipedia)","d":""}},"palace":{"https://en.wikipedia.org/wiki/Idris_of_Libya":{"pre":"The new constitution granted Idris significant personal power, and he remained a crucial player in the country's political system.","hi":"Idris ruled via a palace cabinet, namely his royal diwan, which contained a chef de cabinet, two deputies, and senior advisers.","post":"This diwan worked in consultation with the federal government to determine the policies of the Libyan state.","t":"Idris of Libya (Wikipedia)","d":""}},"green":{"https://en.wikipedia.org/wiki/Martyrs%27_Square,_Tripoli":{"pre":"","hi":"The Martyrs' Square (Arabic: ميدان الشهداء Maydān ash-Shuhadā'), known as Green Square (الساحة الخضراء as-Sāḥah al-Khaḍrā') under the Gaddafi government, Independence Square (ميدان الاستقلال Maydān al-Istiqlāl) during the monarchy, and originally (during Italian colonial rule) known as Piazza Italia (\"Italy Square\"), is a downtown landmark at the bay in the city of Tripoli, Libya.","post":"The main commercial center of the city surrounds the square.","t":"Martyrs' Square, Tripoli (Wikipedia)","d":""}},"fateh":{"https://www.cia.gov/readingroom/document/cia-rdp05-01559r000400370055-5":{"pre":"We are determined not to lay down our arms until the revolutionary program which will transfer the Libyan people from the state of backwardness to the state of progress is achieved.","hi":"PURGE PANEL FORMED IN FORMER TRIPOLI UNIVERSITY Tripoli ARNA in Arabic 1030 GMT 12 Apr 76 LD [Text] Tripoli, 12 April--The central revolutionary, committee was formed yesterday at Al- Fatih University, formerly Tripoli University.","post":"The committee includes students, teachers, workers and employees.","t":"AL QADHDHAFIE ADDRESSES CROWD AT RCC BUIDLING","d":"1976-04-12"},"https://archive.org/details/ufiche-test-document_jprs-82358":{"pre":"There is absolutely no security; the economy has collapsed; the treasury is bankrupt; members of the military are always grumbling and constantly subject to physical elimination; and chaos has become prevalent everywhere.","hi":"News has been received that al-Qadhdhafi recently arrested more than 400 university students and faculty members in Tripoli and Benghazi last April ?. ‘‘o one can believe that a country like Libya whose population is no more than 3 million persons and whose annual revenues from oil is in excess of 25 billion dollars can find itself bankrupt.","post":"No one can believe that the government would issue an order forbidding the importation of more than 83 important goods-—-and some of these are basic goods--because it Cannot pay for its imports.","t":"Near East/North Africa Report No. 2669","d":"1982-12-01"},"https://en.wikipedia.org/wiki/University_of_Tripoli":{"pre":"The university was the site of a student uprising by the Students' Union (SU) during the August 2011 Battle of Tripoli, part of the 2011 Libyan Civil War.","hi":"In 2012, the university was renamed from al-Fateh University to the original name of University of Tripoli. == Political importance == After the 1969 coup by Gaddafi, Tripoli and Benghazi universities were subjected to a crackdown by the Gaddafi government.","post":"From the early 1970s political activity was severely curtailed and by the late 1970s, Gaddafi instructed his followers to arrest any students or staff members who were vocally resistant to his government.","t":"University of Tripoli (Wikipedia)","d":""},"https://en.wikipedia.org/wiki/1976_Libyan_protests":{"pre":"","hi":"The 1976 Libyan protests were demonstrations organized by university students in Tripoli and Benghazi who protested against human rights violations and military control over the civilian population, calling for free and fair elections and for a civilian government.","post":"The protests were repressed and many students were imprisoned. == Background == Muammar Gaddafi became the de facto leader of Libya on 1 September 1969 after leading a group of young Libyan Army officers against King Idris I in a bloodless coup d'état.","t":"1976 Libyan protests (Wikipedia)","d":""},"https://en.wikipedia.org/wiki/Human_rights_in_Libya_under_Muammar_Gaddafi":{"pre":"This included extrajudicial killings, public executions, ethnic cleansing, and the torture of civilians.","hi":"During the Libyan Civil War in 2011, Gaddafi's forces killed allegedly unarmed protestors and indiscriminately bombed civilian areas, drawing condemnation from human rights organizations. == Student protests == On April 7, 1976, university students throughout Libya protested against human rights violations and authoritarian military control over all aspects of civilian lives.","post":"Protesters called for free and fair elections to take place and a more democratic system to be implemented in Libya.","t":"Human rights in Libya under Muammar Gaddafi (Wikipedia)","d":""}},"mk-april1976":{"https://en.wikipedia.org/wiki/1976_Libyan_protests":{"pre":"The protests were repressed and many students were imprisoned. == Background == Muammar Gaddafi became the de facto leader of Libya on 1 September 1969 after leading a group of young Libyan Army officers against King Idris I in a bloodless coup d'état.","hi":"After the king had fled the country, the Revolutionary Command Council (RCC) headed by Gaddafi abolished the monarchy and the old constitution and established the Libyan Arab Republic. == Protests == During the transition to the Jamahiriya, on 7 April 1976, students of universities in Tripoli and Benghazi protested against human rights violations and the military’s control over \"all aspects of life in Libya\"; the students called for free and fair elections to take place and for power to be transferred to a civilian government.","post":"Violent counter-demonstrations took place, with many students imprisoned. == Aftermath == On 7 April 1977, the anniversary of the event, students (including Omar Dabob and Muhammed Ben Saoud) were publicly executed in Benghazi, with anti-Gaddafi military officers executed later in the week.","t":"1976 Libyan protests (Wikipedia)","d":""},"https://en.wikipedia.org/wiki/Human_rights_in_Libya_under_Muammar_Gaddafi":{"pre":"This included extrajudicial killings, public executions, ethnic cleansing, and the torture of civilians.","hi":"During the Libyan Civil War in 2011, Gaddafi's forces killed allegedly unarmed protestors and indiscriminately bombed civilian areas, drawing condemnation from human rights organizations. == Student protests == On April 7, 1976, university students throughout Libya protested against human rights violations and authoritarian military control over all aspects of civilian lives.","post":"Protesters called for free and fair elections to take place and a more democratic system to be implemented in Libya.","t":"Human rights in Libya under Muammar Gaddafi (Wikipedia)","d":""}}};
